import os
import base64
import requests

def extract_receipt_fields(payload, config=None):
    config = config or {}
    api_key = config.get("veryfi_api_key") or os.getenv("VERYFI_API_KEY")
    client_id = config.get("veryfi_client_id") or os.getenv("VERYFI_CLIENT_ID")

    if not api_key or not client_id:
        raise ValueError("Veryfi API key and client ID are required")

    headers = {
        "Content-Type": "application/json",
        "Accept": "application/json",
        "Client-Id": client_id,
        "Authorization": f"apikey {api_key}"
    }

    # Convert file payload to base64 if it's a file path
    if isinstance(payload, str) and os.path.exists(payload):
        with open(payload, "rb") as file:
            payload = base64.b64encode(file.read()).decode("utf-8")

    data = {
        "file_data": payload if isinstance(payload, str) else base64.b64encode(payload).decode("utf-8"),
        "categories": ["groceries", "restaurants", "services"]
    }

    response = requests.post(
        "https://api.veryfi.com/api/v8/partner/documents/",
        headers=headers,
        json=data
    )
    response.raise_for_status()

    result = {
        "merchant": response.json().get("vendor", {}).get("name"),
        "tax": response.json().get("tax"),
        "total": response.json().get("total"),
        "items": [{"description": item.get("description"), "price": item.get("total")} for item in response.json().get("line_items", [])]
    }
    return result
